<?php
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/../includes/security.php';
require_once __DIR__.'/../includes/functions.php';
require_once __DIR__.'/../includes/portal.php';
requireRole(['SuperAdmin']);$items=$pdo->query('SELECT id,username,email,full_name,role,is_active FROM users ORDER BY role,full_name')->fetchAll();portalStart('User Management','users.php');echo '<div class="portal-panel"><h2>Create administrator</h2><form class="portal-form" method="post" action="../portal_action.php">'.csrf_field().'<input type="hidden" name="action" value="create_admin"><input type="hidden" name="back" value="users.php"><label>Name<input name="full_name" required></label><label>Username<input name="username" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="10" maxlength="72" required></label><button class="portal-button">Create administrator</button></form></div>';foreach($items as $u){echo '<div class="portal-panel"><strong>'.h($u['full_name']).'</strong> · '.h($u['role']).' · '.h($u['email']).' · '.($u['is_active']?'Active':'Inactive');if($u['role']==='Admin')echo '<form method="post" action="../portal_action.php">'.csrf_field().'<input type="hidden" name="action" value="toggle_user"><input type="hidden" name="back" value="users.php"><input type="hidden" name="id" value="'.h($u['id']).'"><button class="portal-button secondary">'.($u['is_active']?'Deactivate':'Reactivate').'</button></form>';echo '</div>';}portalEnd();